import React, { useState, useEffect } from 'react';
import { Check, UploadCloud, X, Search, ArrowUpDown, Eye, Play, Clock } from 'lucide-react';
import axios from 'axios';

// Colors from the main app
const colors = {
  primary: '#f7abff',    // Pink background
  secondary: '#2f2a2f',  // Dark gray/black
  accent: '#3CDFFF',     // Cyan blue accent
  darkAccent: '#620f87', // Deep purple
  light: '#f9f9f9',      // White text
  midGray: '#797979',    // Mid gray
  successGreen: '#4ADE80',
  warningOrange: '#F97316',
  errorRed: '#EF4444'
};

const ShotList = () => {
  // State for shot list data - load from localStorage or start empty
  const [shots, setShots] = useState(() => {
    const savedShots = localStorage.getItem('melodicJustice_shots');
    return savedShots ? JSON.parse(savedShots) : [];
  });
  
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  
  // State for filtering and sorting
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [sceneFilter, setSceneFilter] = useState('All');
  const [sortBy, setSortBy] = useState({ field: 'id', direction: 'asc' });
  
  // State for file upload
  const [file, setFile] = useState(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isUploading, setIsUploading] = useState(false);

  // State for shot modal
  const [selectedShot, setSelectedShot] = useState(null);
  const [showShotModal, setShowShotModal] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [newNote, setNewNote] = useState('');

  // Derived state
  const [uniqueScenes, setUniqueScenes] = useState([]);
  
  // Save shots to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('melodicJustice_shots', JSON.stringify(shots));
  }, [shots]);
  
  // Update unique scenes when shots change
  useEffect(() => {
    if (shots.length > 0) {
      const scenes = [...new Set(shots.map(shot => shot.scene))];
      setUniqueScenes(['All', ...scenes.sort()]);
    } else {
      setUniqueScenes(['All']);
    }
  }, [shots]);
  
  // Fetch shots from API
  const fetchShots = async () => {
    setIsLoading(true);
    setError(null);
    
    try {
      const response = await axios.get('http://localhost:5000/api/shots');
      if (response.data && response.data.length > 0) {
        const sortedShots = response.data.sort((a, b) => {
          if (!isNaN(a.id) && !isNaN(b.id)) {
            return parseInt(a.id) - parseInt(b.id);
          }
          return a.id.localeCompare(b.id);
        });
        
        setShots(sortedShots);
      }
    } catch (error) {
      console.error('Error fetching shots:', error);
      // Don't show error if we're using localStorage data
      if (shots.length === 0) {
        setError('Unable to connect to server. You can still import shots locally.');
      }
    } finally {
      setIsLoading(false);
    }
  };
  
  // Handle file upload
  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      // Check file extension
      const allowedTypes = ['.xlsx', '.xls', '.csv'];
      const fileExt = selectedFile.name.substring(selectedFile.name.lastIndexOf('.')).toLowerCase();
      
      if (!allowedTypes.includes(fileExt)) {
        setError('Please upload an Excel (.xlsx, .xls) or CSV (.csv) file.');
        return;
      }
      
      setFile(selectedFile);
      setError(null);
    }
  };
  
  const handleFileUpload = async () => {
    if (!file) return;
    
    setIsUploading(true);
    setUploadProgress(0);
    setError(null);
    
    // Create FormData for file upload
    const formData = new FormData();
    formData.append('file', file);
    
    try {
      // First try to upload to server
      const response = await axios.post('http://localhost:5000/api/shots/import', formData, {
        headers: {
          'Content-Type': 'multipart/form-data'
        },
        onUploadProgress: (progressEvent) => {
          const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total);
          setUploadProgress(percentCompleted);
        }
      });
      
      if (response.data && response.data.shots) {
        setShots(response.data.shots);
      }
    } catch (error) {
      console.error('Server upload failed, trying local processing:', error);
      
      // If server upload fails, try to process locally
      try {
        await processFileLocally(file);
      } catch (localError) {
        setError('Failed to process file. Please check the format and try again.');
        console.error('Local processing failed:', localError);
      }
    } finally {
      setIsUploading(false);
      setFile(null);
      setUploadProgress(0);
    }
  };
  
  // Process file locally if server is unavailable
  const processFileLocally = async (file) => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      
      reader.onload = async (e) => {
        try {
          const data = e.target.result;
          
          if (file.name.endsWith('.csv')) {
            // Parse CSV
            const lines = data.split('\n');
            const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
            
            const newShots = [];
            for (let i = 1; i < lines.length; i++) {
              if (!lines[i].trim()) continue;
              
              const values = lines[i].split(',');
              const shot = {};
              
              headers.forEach((header, index) => {
                if (header.includes('id') || header.includes('shot')) {
                  shot.id = values[index]?.trim() || String(i).padStart(3, '0');
                } else if (header.includes('scene')) {
                  shot.scene = values[index]?.trim() || 'Unknown';
                } else if (header.includes('desc')) {
                  shot.description = values[index]?.trim() || '';
                } else if (header.includes('status')) {
                  shot.status = values[index]?.trim() || 'Not Started';
                } else if (header.includes('note')) {
                  shot.notes = values[index]?.trim() || '';
                }
              });
              
              // Ensure required fields
              if (!shot.id) shot.id = String(i).padStart(3, '0');
              if (!shot.scene) shot.scene = 'Unknown';
              if (!shot.description) shot.description = 'Shot ' + shot.id;
              if (!shot.status) shot.status = 'Not Started';
              if (!shot.notes) shot.notes = '';
              
              shot.lastUpdate = new Date().toISOString();
              newShots.push(shot);
            }
            
            setShots(prevShots => [...prevShots, ...newShots]);
            resolve();
          } else {
            // Handle Excel files - for now, just reject if server isn't available
            reject(new Error('Excel processing requires server connection'));
          }
        } catch (error) {
          reject(error);
        }
      };
      
      reader.onerror = () => reject(new Error('Failed to read file'));
      reader.readAsText(file);
    });
  };
  
  // Handle status change for a shot
  const handleStatusChange = async (shotId, newStatus) => {
    try {
      // Find the shot and update its status
      const updatedShots = shots.map(shot => 
        shot.id === shotId ? { 
          ...shot, 
          status: newStatus, 
          lastUpdate: new Date().toISOString() 
        } : shot
      );
      
      // Optimistic update
      setShots(updatedShots);
      
      // Try to update on server
      try {
        await axios.put(`http://localhost:5000/api/shots/${shotId}`, { 
          status: newStatus,
          lastUpdate: new Date().toISOString()
        });
      } catch (error) {
        console.log('Server update failed, changes saved locally only');
      }
    } catch (error) {
      setError('Failed to update shot status. Please try again.');
      console.error('Error updating shot status:', error);
    }
  };

  // Handle adding a note to a shot
  const handleAddNote = async () => {
    if (!selectedShot || !newNote.trim()) return;
    
    try {
      const timestamp = new Date().toLocaleDateString() + ' ' + new Date().toLocaleTimeString();
      const updatedNotes = selectedShot.notes 
        ? `${selectedShot.notes}\n[${timestamp}] ${newNote}` 
        : `[${timestamp}] ${newNote}`;
      
      const updatedShot = {
        ...selectedShot,
        notes: updatedNotes,
        lastUpdate: new Date().toISOString()
      };
      
      // Optimistic update
      setShots(shots.map(shot => 
        shot.id === selectedShot.id ? updatedShot : shot
      ));
      
      setSelectedShot(updatedShot);
      setNewNote('');
      
      // Try to update on server
      try {
        await axios.put(`http://localhost:5000/api/shots/${selectedShot.id}`, {
          notes: updatedNotes,
          lastUpdate: new Date().toISOString()
        });
      } catch (error) {
        console.log('Server update failed, changes saved locally only');
      }
    } catch (error) {
      setError('Failed to update shot notes. Please try again.');
      console.error('Error updating shot notes:', error);
    }
  };
  
  // Handle sorting
  const handleSort = (field) => {
    setSortBy(prev => ({
      field,
      direction: prev.field === field && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };
  
  // Open shot details modal
  const handleOpenShotDetails = (shot) => {
    setSelectedShot(shot);
    setShowShotModal(true);
    setEditMode(false);
  };
  
  // Close shot details modal
  const handleCloseShotModal = () => {
    setShowShotModal(false);
    setSelectedShot(null);
    setEditMode(false);
    setNewNote('');
  };
  
  // Filter and sort shots
  const filteredAndSortedShots = shots
    .filter(shot => {
      // Apply search filter
      const matchesSearch = 
        shot.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        shot.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (shot.notes && shot.notes.toLowerCase().includes(searchTerm.toLowerCase()));
      
      // Apply status filter
      const matchesStatus = statusFilter === 'All' || shot.status === statusFilter;
      
      // Apply scene filter
      const matchesScene = sceneFilter === 'All' || shot.scene === sceneFilter;
      
      return matchesSearch && matchesStatus && matchesScene;
    })
    .sort((a, b) => {
      // Apply sorting
      const direction = sortBy.direction === 'asc' ? 1 : -1;
      
      if (sortBy.field === 'id') {
        if (!isNaN(a.id) && !isNaN(b.id)) {
          return direction * (parseInt(a.id) - parseInt(b.id));
        }
        return direction * a.id.localeCompare(b.id);
      }
      
      if (sortBy.field === 'lastUpdate') {
        return direction * (new Date(a.lastUpdate || 0) - new Date(b.lastUpdate || 0));
      }
      
      if (a[sortBy.field] < b[sortBy.field]) return -1 * direction;
      if (a[sortBy.field] > b[sortBy.field]) return 1 * direction;
      return 0;
    });
  
  // Calculate stats
  const totalShots = shots.length;
  const completeShots = shots.filter(shot => shot.status === 'Complete').length;
  const inProgressShots = shots.filter(shot => shot.status === 'In Progress').length;
  const notStartedShots = shots.filter(shot => shot.status === 'Not Started').length;
  
  // Get status color
  const getStatusColor = (status) => {
    switch (status) {
      case 'Complete':
        return colors.successGreen;
      case 'In Progress':
        return colors.warningOrange;
      case 'Not Started':
      default:
        return colors.midGray;
    }
  };

  // Format date for display
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString() + ' ' + date.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
    } catch (e) {
      return 'Invalid date';
    }
  };
  
  return (
    <div className="rounded-lg p-4" style={{ backgroundColor: colors.secondary }}>
      {/* Header with stats */}
      <div className="flex flex-wrap justify-between items-center mb-6">
        <div>
          <h2 className="text-xl font-bold text-white">Shot List</h2>
          <p className="text-gray-400">Track and manage your animation shots</p>
        </div>
        
        <div className="flex space-x-4 text-white">
          <div className="text-center">
            <div className="text-2xl font-bold">{totalShots}</div>
            <div className="text-sm text-gray-400">Total Shots</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold" style={{ color: colors.successGreen }}>{completeShots}</div>
            <div className="text-sm text-gray-400">Complete</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold" style={{ color: colors.warningOrange }}>{inProgressShots}</div>
            <div className="text-sm text-gray-400">In Progress</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold" style={{ color: colors.midGray }}>{notStartedShots}</div>
            <div className="text-sm text-gray-400">Not Started</div>
          </div>
        </div>
      </div>
      
      {/* Progress bar */}
      <div className="mb-6">
        <div className="flex justify-between mb-1">
          <div className="text-sm text-white">Overall Progress</div>
          <div className="text-sm text-white">{Math.round((completeShots / totalShots) * 100) || 0}%</div>
        </div>
        <div className="w-full h-3 bg-gray-800 rounded-full overflow-hidden">
          <div className="flex h-full">
            <div 
              className="h-full"
              style={{ 
                width: `${(completeShots / totalShots) * 100}%`,
                backgroundColor: colors.successGreen
              }}
            ></div>
            <div 
              className="h-full"
              style={{ 
                width: `${(inProgressShots / totalShots) * 100}%`,
                backgroundColor: colors.warningOrange
              }}
            ></div>
          </div>
        </div>
      </div>
      
      {/* Filter bar */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        <div className="relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-5 w-5 text-gray-400" />
          </div>
          <input
            type="text"
            placeholder="Search shots..."
            className="bg-gray-800 text-white pl-10 pr-4 py-2 rounded w-full border border-gray-700"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        
        <div className="flex space-x-2">
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="bg-gray-800 text-white px-3 py-2 rounded border border-gray-700 flex-grow"
          >
            <option value="All">All Statuses</option>
            <option value="Complete">Complete</option>
            <option value="In Progress">In Progress</option>
            <option value="Not Started">Not Started</option>
          </select>
          
          <select
            value={sceneFilter}
            onChange={(e) => setSceneFilter(e.target.value)}
            className="bg-gray-800 text-white px-3 py-2 rounded border border-gray-700 flex-grow"
          >
            {uniqueScenes.map(scene => (
              <option key={scene} value={scene}>{scene}</option>
            ))}
          </select>
        </div>
        
        <div className="flex space-x-2">
          <div className="relative flex-grow">
            <input
              type="file"
              id="shot-list-upload"
              className="hidden"
              accept=".xlsx,.xls,.csv"
              onChange={handleFileChange}
            />
            <label
              htmlFor="shot-list-upload"
              className="cursor-pointer bg-gray-800 text-white px-3 py-2 rounded border border-gray-700 flex items-center justify-center w-full"
            >
              <UploadCloud className="h-5 w-5 mr-2" />
              {file ? file.name : 'Import Excel...'}
            </label>
          </div>
          
          <button
            className={`px-3 py-2 rounded flex items-center justify-center ${file ? 'bg-purple-600 text-white' : 'bg-gray-700 text-gray-400 cursor-not-allowed'}`}
            disabled={!file || isUploading}
            onClick={handleFileUpload}
            style={{ backgroundColor: file ? colors.accent : undefined }}
          >
            Upload
          </button>
        </div>
      </div>
      
      {/* Upload progress */}
      {isUploading && (
        <div className="mb-4">
          <div className="text-sm text-white mb-1">Uploading: {uploadProgress}%</div>
          <div className="w-full bg-gray-700 h-2 rounded-full">
            <div 
              className="h-full rounded-full"
              style={{ 
                width: `${uploadProgress}%`,
                backgroundColor: colors.accent
              }}
            ></div>
          </div>
        </div>
      )}
      
      {/* Error message */}
      {error && (
        <div className="mb-4 p-3 bg-red-900 bg-opacity-30 border border-red-800 rounded text-red-100">
          {error}
        </div>
      )}
      
      {/* Shot list table */}
      <div className="overflow-x-auto bg-gray-900 rounded-lg">
        <table className="w-full">
          <thead>
            <tr className="border-b border-gray-800">
              <th 
                className="px-4 py-3 text-left text-gray-400 cursor-pointer"
                onClick={() => handleSort('id')}
              >
                <div className="flex items-center">
                  Shot ID
                  {sortBy.field === 'id' && (
                    <ArrowUpDown className="h-4 w-4 ml-1" />
                  )}
                </div>
              </th>
              <th 
                className="px-4 py-3 text-left text-gray-400 cursor-pointer"
                onClick={() => handleSort('scene')}
              >
                <div className="flex items-center">
                  Scene
                  {sortBy.field === 'scene' && (
                    <ArrowUpDown className="h-4 w-4 ml-1" />
                  )}
                </div>
              </th>
              <th className="px-4 py-3 text-left text-gray-400">Description</th>
              <th className="px-4 py-3 text-left text-gray-400">Status</th>
              <th 
                className="px-4 py-3 text-left text-gray-400 cursor-pointer"
                onClick={() => handleSort('lastUpdate')}
              >
                <div className="flex items-center">
                  Last Updated
                  {sortBy.field === 'lastUpdate' && (
                    <ArrowUpDown className="h-4 w-4 ml-1" />
                  )}
                </div>
              </th>
              <th className="px-4 py-3 text-center text-gray-400">Actions</th>
            </tr>
          </thead>
          <tbody>
            {isLoading ? (
              <tr>
                <td colSpan="6" className="px-4 py-8 text-center text-gray-400">
                  Loading shot list...
                </td>
              </tr>
            ) : filteredAndSortedShots.length === 0 ? (
              <tr>
                <td colSpan="6" className="px-4 py-8 text-center text-gray-400">
                  {shots.length === 0 ? 'No shots added yet. Import a shot list or create new shots.' : 'No shots found matching your filters.'}
                </td>
              </tr>
            ) : (
              filteredAndSortedShots.map(shot => (
                <tr key={shot.id} className="border-b border-gray-800 hover:bg-gray-800">
                  <td className="px-4 py-3 text-white">{shot.id}</td>
                  <td className="px-4 py-3 text-white">{shot.scene}</td>
                  <td className="px-4 py-3 text-white">{shot.description}</td>
                  <td className="px-4 py-3">
                    <select
                      value={shot.status}
                      onChange={(e) => handleStatusChange(shot.id, e.target.value)}
                      className="px-2 py-1 rounded text-white"
                      style={{ 
                        backgroundColor: 'transparent',
                        borderColor: getStatusColor(shot.status),
                        borderWidth: '1px',
                        color: getStatusColor(shot.status)
                      }}
                    >
                      <option value="Complete" style={{ backgroundColor: '#1a1a1a' }}>Complete</option>
                      <option value="In Progress" style={{ backgroundColor: '#1a1a1a' }}>In Progress</option>
                      <option value="Not Started" style={{ backgroundColor: '#1a1a1a' }}>Not Started</option>
                    </select>
                  </td>
                  <td className="px-4 py-3 text-gray-400">
                    {formatDate(shot.lastUpdate)}
                  </td>
                  <td className="px-4 py-3 text-center">
                    <button 
                      onClick={() => handleOpenShotDetails(shot)}
                      className="bg-gray-700 p-1 rounded hover:bg-gray-600"
                    >
                      <Eye className="h-4 w-4 text-white" />
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
      
      {/* Shot count */}
      <div className="mt-4 text-sm text-gray-400">
        Showing {filteredAndSortedShots.length} of {totalShots} shots
      </div>
      
      {/* Shot details modal */}
      {showShotModal && selectedShot && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-900 rounded-lg w-full max-w-3xl max-h-[80vh] overflow-hidden flex flex-col">
            <div className="flex justify-between items-center p-4 border-b border-gray-800">
              <h3 className="text-lg font-bold text-white">Shot {selectedShot.id}</h3>
              <button onClick={handleCloseShotModal} className="text-gray-400 hover:text-white">
                <X className="h-5 w-5" />
              </button>
            </div>
            
            <div className="flex-grow overflow-y-auto p-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                <div>
                  <div className="text-gray-400 text-sm mb-1">Scene</div>
                  <div className="text-white">{selectedShot.scene}</div>
                </div>
                
                <div>
                  <div className="text-gray-400 text-sm mb-1">Status</div>
                  <div className="inline-block px-2 py-1 rounded" style={{ backgroundColor: getStatusColor(selectedShot.status), color: 'white' }}>
                    {selectedShot.status}
                  </div>
                </div>
                
                <div className="md:col-span-2">
                  <div className="text-gray-400 text-sm mb-1">Description</div>
                  <div className="text-white">{selectedShot.description}</div>
                </div>
                
                <div className="md:col-span-2">
                  <div className="text-gray-400 text-sm mb-1">Last Updated</div>
                  <div className="text-white flex items-center gap-2">
                    <Clock className="h-4 w-4" />
                    {formatDate(selectedShot.lastUpdate)}
                  </div>
                </div>
              </div>
              
              <div className="mt-6">
                <h4 className="text-white text-md font-medium mb-2">Notes</h4>
                <div className="bg-gray-800 rounded-lg p-4 text-gray-300 min-h-[100px] whitespace-pre-line">
                  {selectedShot.notes || 'No notes yet.'}
                </div>
              </div>
              
              <div className="mt-6">
                <h4 className="text-white text-md font-medium mb-2">Add Note</h4>
                <div className="flex">
                  <textarea
                    value={newNote}
                    onChange={(e) => setNewNote(e.target.value)}
                    placeholder="Enter new note about this shot..."
                    className="flex-grow bg-gray-800 border border-gray-700 rounded-l p-2 text-white"
                    rows={2}
                  />
                  <button
                    onClick={handleAddNote}
                    disabled={!newNote.trim()}
                    className="px-4 rounded-r flex items-center justify-center"
                    style={{ 
                      backgroundColor: newNote.trim() ? colors.accent : '#4a4a4a',
                      color: newNote.trim() ? 'white' : '#888'
                    }}
                  >
                    Add
                  </button>
                </div>
              </div>
            </div>
            
            <div className="flex justify-between p-4 border-t border-gray-800">
              <div className="flex space-x-2">
                <button 
                  className="flex items-center space-x-1 px-3 py-1 rounded bg-gray-800 text-white hover:bg-gray-700"
                  onClick={() => handleStatusChange(selectedShot.id, 'In Progress')}
                >
                  <Play className="h-4 w-4" />
                  <span>Start Work</span>
                </button>
                
                <button 
                  className="flex items-center space-x-1 px-3 py-1 rounded bg-gray-800 text-white hover:bg-gray-700"
                  onClick={() => handleStatusChange(selectedShot.id, 'Complete')}
                >
                  <Check className="h-4 w-4" />
                  <span>Mark Complete</span>
                </button>
              </div>
              
              <button 
                className="flex items-center space-x-1 px-3 py-1 rounded"
                style={{ backgroundColor: colors.accent, color: 'white' }}
                onClick={handleCloseShotModal}
              >
                <span>Close</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ShotList;
